public int sherlockAndAnagrams(String s) {
    int n = s.length();
    List<String> subs = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            char[] c = s.substring(i, j).toCharArray();
            Arrays.sort(c);
            subs.add(new String(c));
        }
    }
    int pairs = 0;
    for (int a = 0; a < subs.size(); a++) {
        for (int b = a + 1; b < subs.size(); b++) {
            if (subs.get(a).equals(subs.get(b))) pairs++;
        }
    }
    return pairs;
}

