code.java:
public int sherlockAndAnagrams(String s) {
    Map<String, Integer> count = new HashMap<>();
    int n = s.length();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            char[] c = s.substring(i, j).toCharArray();
            Arrays.sort(c);
            String sig = new String(c);
            count.merge(sig, 1, Integer::sum);
        }
    }
    int pairs = 0;
    for (int k : count.values()) {
        pairs += k * (k - 1) / 2;
    }
    return pairs;
}

