def sherlock_and_anagrams(self, s: str) -> int:
    count: dict[str, int] = {}
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            sig = "".join(sorted(s[i:j]))
            count[sig] = count.get(sig, 0) + 1
    return sum(k * (k - 1) // 2 for k in count.values())

